function generatedImageTurnKey(threadId: string, turnId?: string): string {
  return `${threadId}:${turnId ?? "active"}`;
}
/** Every staged image on a thread, whatever provider turn it belongs to.
 * Deleting the thread's owner makes all of them unattachable at once, so
 * they go together rather than waiting for a per-turn retirement that will
 * now never arrive. */
function purgeGeneratedImagesForThread(threadId: string): void {
  for (const [key, attachments] of generatedImagesByTurn) {
    if (!key.startsWith(`${threadId}:`)) continue;
    generatedImagesByTurn.delete(key);
    for (const attachment of attachments) {
      try { deleteAttachment(attachment.path); } catch { /* already gone; accounting invalidates on failure */ }
    }
  }
}

const retiredProviderTurns = new RetiredTurnRegistry();
const pendingCancelledProviderHandshakes = new PendingTurnCancellations();

function markCancelledProviderHandshake(threadId: string, ownerId: string): void {
  pendingCancelledProviderHandshakes.mark(threadId, ownerId);
}

function clearCancelledProviderHandshake(threadId: string, ownerId: string): void {
  pendingCancelledProviderHandshakes.clear(threadId, ownerId);
}

function retireProviderTurn(turnId: string): void {
  retiredProviderTurns.retire(turnId);
  // A stopped/replaced turn is never folded again. Delete only image files
  // that were staged for that exact provider turn so unattached output does
  // not accumulate invisibly on disk.
  for (const [key, attachments] of generatedImagesByTurn) {
    if (!key.endsWith(`:${turnId}`)) continue;
    generatedImagesByTurn.delete(key);
    for (const attachment of attachments) {
      try { deleteAttachment(attachment.path); } catch { /* already gone; accounting invalidates on failure */ }
    }
  }
}

function shouldIgnoreProviderEvent(event: RuntimeEvent): boolean {
  // The Chief's hidden proposal turn (runChiefProposalTurn owns its events):
  // nothing of it reaches a thread, a window or another bot's bookkeeping.
  if (chiefProposals.ignores(event.threadId)) return true;
  // A PIP reflection attempt runs under a pseudo thread id that no window, thread or bot bookkeeping may see
  // (design §3.3): `pip-reflect:<botId>:<runId>:<family>:<attempt>`.
  if (isPipReflectThread(event.threadId)) return true;
  // Some adapters publish completion/error synchronously just before their
  // sendTurn promise resolves. Stop can already have cancelled that handshake,
  // but its returned turn id is not available to retire yet. Quarantine the
  // narrow pre-id window and tombstone any id it reveals; the broad gate is
  // time-bounded so a broken promise cannot suppress a later turn forever.
  if (isTurnEventQuarantined(pendingCancelledProviderHandshakes, retiredProviderTurns, event)) return true;
  if (event.type !== "session.exited" || event.turnId !== undefined) return false;
  return store.botByThread(event.threadId)?.busy === true || Boolean(store.groupByThread(event.threadId)?.busyBotId);
}

function directTurnClaimIsCurrent(botId: string, claimId: string, threadId: string): boolean {
  const run=directRuns.get(threadId);
  return run?.generation===claimId&&run.botId===botId&&run.phase!=="stopping"&&store.taskByThread(botId,threadId)?.busy===true;
}

function directTurnClaimExists(botId: string, claimId: string, threadId: string): boolean {
  const claim = directTurnDispatchClaims.get(threadId);
  return claim?.id === claimId && claim.botId === botId;
}

function markDirectTurnDispatching(botId: string, claimId: string, threadId: string): boolean {
  if (!directTurnClaimIsCurrent(botId, claimId, threadId)) return false;
  directTurnDispatchClaims.set(threadId, { id: claimId, botId, threadId, phase: "dispatching" });
  directRuns.dispatch({threadId,generation:claimId});
  return true;
}

function clearDirectTurnDispatch(threadId: string, claimId: string): void {
  if (directTurnDispatchClaims.get(threadId)?.id === claimId) directTurnDispatchClaims.delete(threadId);
}

function cancelDirectTurnDispatch(botId: string, expectedThreadId?: string, stopNote?: string): DirectTurnDispatchClaim | null {
  const threadId=expectedThreadId??store.bot(botId)?.threadId;
  if(!threadId)return null;
  const generation = directRuns.get(threadId)?.generation ?? internalTurnOwners.get(threadId)?.generation;
  const requestId = generation ? turnRequestByGeneration.get(generation) : undefined;
  const cardRequestId = requestId ?? workAdmission.liveTurns({ botId }).find(held => held.threadId === threadId)?.requestId;
  if (cardRequestId) projectCardExecutor.requestStop(cardRequestId, stopNote);
  if(internalTurnOwners.get(threadId)?.botId===botId)revokeInternalThread(threadId);
  const run=directRuns.get(threadId);if(run&&run.botId===botId)directRuns.cancel(run);
  const claim = directTurnDispatchClaims.get(threadId);
  if (!claim || claim.botId!==botId) return null;
  recordMemorySettlement(claim.threadId, claim.id, "cancelled");
  directTurnDispatchClaims.delete(threadId);
  // Setup has not called the adapter yet, so there is no provider handshake
  // (and no unknown turn id) to quarantine. Dispatching is the only phase in
  // which a late provider event can exist.
  if (claim.phase === "dispatching") {
    markCancelledProviderHandshake(claim.threadId, `direct:${claim.id}`);
  }
  // Keep setup ownership until the guarded send resolves and retires its
  // provider turn id. Some adapters can emit completion synchronously just
  // before sendTurn returns; making the bot idle here would let a replacement
  // start early enough for those old events to settle the replacement.
  return claim;
}

/** The browser is an optional tool, never a precondition of a turn. When its
 * binding cannot be established (the engine's version check timed out under
 * load, the binary is gone), the turn runs WITHOUT browser tools: the primer's
 * browser-absent clause then tells the bot the truth, and the caller leaves
 * one quiet note in the conversation. It used to throw into the turn's setup
 * catch and fail the whole request — with a card that sent the person to
 * Provider settings for a failure no provider was involved in. */
type BrowserBinding = { profileKey: string; integration: { command: string; args: string[]; env: Record<string, string> } };
async function browserIntegration(botId: string, profile: string | undefined, threadId: string, stillValid: () => boolean = () => true, ownerId: string = randomUUID()): Promise<BrowserBinding | { unavailable: string; extension?: true } | null> {
  const extensionBot = store.bot(botId);
  if (extensionBot?.useMyChrome && extensionBot.browserTransport === "extension") {
    try {
      const binding = await browserExtensionRuntime().bind(extensionBot, threadId);
      if (!stillValid()) return null;
      await releaseBrowserCapabilityForThread(threadId);
      if (!stillValid()) return null;
      const control = controlIntegration(botId, threadId, ownerId);
      extensionBrowserThreads.set(threadId, { bindingId: binding.bindingId, botId, ownerId });
      unifiedBrowserThreads.set(threadId, { botId, ownerId, profileKey: binding.bindingId, profile });
      return { profileKey: binding.bindingId, integration: { command: process.execPath, args: [SPAWNED_PROXIES.unifiedBrowser], env: {
        ...AGENTS_NODE_FLAG, MURAGE_BOT_ID: botId, MURAGE_THREAD_ID: threadId,
        // A card waits up to fifteen minutes for a person; the call outlives that and the action after it.
        // One deadline for the external MCP client and this built-in mount (shared constant), and the extension transport so the proxy defers to the executor.
        MURAGE_BROWSER_TRANSPORT: "extension", MURAGE_BROWSER_CALL_TIMEOUT_MS: String(BROWSER_EXTENSION_CALL_TIMEOUT_MS),
        MURAGE_CONTROL_TOKEN: control.token, MURAGE_CONTROL_URL: control.url,
      } } };
    } catch (error) { return { unavailable: redactSecretsInText(error instanceof Error ? error.message : "Browser extension unavailable").slice(0, 200), extension: true }; }
  }
  if (browserEngineStatus().kind !== "ready") return null;
  let binding: Awaited<ReturnType<typeof unifiedBrowserBinding>>;
  try {
    binding = await unifiedBrowserBinding(botId, profile);
  } catch (error) {
    // Chrome closed or its remote debugging off: the turn runs without a
    // browser rather than failing, and the chat says how to turn it on.
    if (error && typeof error === "object" && "userChromeNotReady" in error) return { unavailable: USER_CHROME_UNREACHABLE_REASON };
    const reason = redactSecretsInText(error instanceof Error ? error.message : String(error)).trim().slice(0, 120);
    console.warn(`[browser] continuing this turn without the browser: ${reason}`);
    return { unavailable: reason };
  }
  if (!stillValid()) return null;
  await releaseBrowserCapabilityForThread(threadId);
  if (!stillValid()) return null;
  const control = controlIntegration(botId, threadId, ownerId);
  unifiedBrowserThreads.set(threadId, { botId, ownerId, profileKey: binding.key, profile });
  return { profileKey: binding.key, integration: { command: process.execPath, args: [SPAWNED_PROXIES.unifiedBrowser], env: {
    ...AGENTS_NODE_FLAG, MURAGE_BOT_ID: botId, MURAGE_THREAD_ID: threadId,
    // The owner's Chrome waits on their Allow (up to USER_CHROME_ALLOW_WAIT_MS, twice).
    ...(store.bot(botId)?.useMyChrome ? { MURAGE_BROWSER_CALL_TIMEOUT_MS: String(USER_CHROME_ALLOW_WAIT_MS * 2 + 30_000) } : {}),
    MURAGE_CONTROL_TOKEN: control.token, MURAGE_CONTROL_URL: control.url,
  } } };
}

/** The one note a turn that runs without its browser leaves behind. */
function noteBrowserUnavailable(threadId: string, bot: { id: string; name: string; color: string }, reason: string): void {
  store.appendMessage(threadId, {
    role: "bot",
    kind: "activity",
    ...(store.groupByThread(threadId) ? { from: { botId: bot.id, name: bot.name, color: bot.color } } : {}),
    // ok:true like a folder-trust notice: neutral, not a failure, no card.
    tool: { name: browserUnavailableActivityName(reason), ok: true },
  });
}

