        const before = anchors && (!event.turnId || !anchors.turnId || anchors.turnId === event.turnId) ? anchors.rows.get(event.beforeItemId!) : undefined;
        pushMessage({ role: "bot", kind: "text", text: shown, turnId: event.turnId }, before);
